    output: { questionVersionDocument: "stem, options, answerKey, grade, contentHash, source checksum, qualificationStatus", qualificationStatus: "pending_qualification / revision_required / out_of_scope", inputValidation: "pass atau review dengan reasons" },
    cautions: ["Hash menjaga keterlacakan, bukan bukti bahwa isi benar.", "Runtime mengecek contentRegistry untuk ID yang dikenal. Unknown ID tidak otomatis berarti konten telah disetujui; provenance gate masih berlaku."],
