    example: "Ilustrasi keluaran: verifiedMinimalSolution='3 + 2 = 5, maka B'; intendedDifficulty.action='classify', label='Easy', dependentSteps=1, routineStatus='familiar_routine', gradeRelativeRationale='Penjumlahan sederhana dengan benda familiar untuk kelas 1'. Label ini usulan AI yang masih memerlukan ahli.",
    output: { status: "success atau failed", contentStatus: "valid/concern/insufficient_evidence", answerKeyStatus: "verified/conflict/unverifiable", heads: "mathCognitiveDomain, knowledgeDimension, intendedDifficulty", isGoldLabel: false },
    cautions: ["Self-consistency LLM bukan calibrated probability of correctness.", "Rationale dan evidence adalah ringkasan keputusan yang dapat dicek; diagram tidak mengklaim mengetahui pikiran internal model.", "IndoBERT text-only tidak melihat imageRefs secara langsung. Transkripsi visual perlu benar dan terverifikasi."],
    sources: [{ path: "app/llm/silver.py", symbol: "silver_rubric, build_silver_prompt, SilverLabelOutput, DifficultyEvidenceProfile, GeminiSilverAdapter" }, { path: "configs/rubric_math_3x4x3_v2.yaml", symbol: "Rubrik SD grade-aware" }]
